use std::sync::atomic::{AtomicU32, Ordering};

static LOG: AtomicU32 = AtomicU32::new(0);

struct FieldA;
impl Drop for FieldA {
    fn drop(&mut self) {
        let cur = LOG.load(Ordering::SeqCst);
        LOG.store(cur * 10 + 1, Ordering::SeqCst);
    }
}

struct FieldB;
impl Drop for FieldB {
    fn drop(&mut self) {
        let cur = LOG.load(Ordering::SeqCst);
        LOG.store(cur * 10 + 2, Ordering::SeqCst);
    }
}

struct Container {
    ⟦f1⟧: FieldA,
    ⟦f2⟧: FieldB,
}

fn run_container() -> u32 {
    LOG.store(0, Ordering::SeqCst);
    {
        let _c = Container {
            a: FieldA,
            b: FieldB,
        };
    }
    LOG.load(Ordering::SeqCst)
}
